Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
$env:NPM_CONFIG_LOGLEVEL = "error"

$Root = (Get-Location).Path
$RelativePath = "app/login/page.tsx"
$TargetPath = Join-Path $Root "app\login\page.tsx"
$BackupDirectory = Join-Path $Root ".orcaly-backups"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupPath = Join-Path $BackupDirectory "login-signature-v3-$Timestamp.tsx"

$LoginBase64 = @'

'@

function Write-Section([string]$Text) {
    Write-Host ""
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
}

function Restore-Login {
    if (Test-Path -LiteralPath $BackupPath) {
        Write-Host "[AVISO] Restaurando o login anterior..." -ForegroundColor Yellow

        Copy-Item `
            -LiteralPath $BackupPath `
            -Destination $TargetPath `
            -Force
    }
}

Write-Section "ORCALY - LOGIN SIGNATURE V3"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

git rev-parse --is-inside-work-tree | Out-Null

if ($LASTEXITCODE -ne 0) {
    throw "A pasta atual não é um repositório Git."
}

if (-not (Test-Path -LiteralPath $TargetPath)) {
    throw "Arquivo não encontrado: $RelativePath"
}

New-Item `
    -ItemType Directory `
    -Path $BackupDirectory `
    -Force | Out-Null

Copy-Item `
    -LiteralPath $TargetPath `
    -Destination $BackupPath `
    -Force

Write-Host "[OK] Backup: $BackupPath" -ForegroundColor Green

try {
    Write-Section "APLICANDO LOGIN PREMIUM"

    $CleanBase64 = $LoginBase64 -replace "\s", ""
    $Bytes = [Convert]::FromBase64String($CleanBase64)

    [System.IO.File]::WriteAllBytes(
        $TargetPath,
        $Bytes
    )

    $Content = [System.IO.File]::ReadAllText(
        $TargetPath,
        [System.Text.Encoding]::UTF8
    )

    $RequiredTexts = @(
        "ORCALY_LOGIN_SIGNATURE_V3",
        "ORCALY_LOGIN_DEFAULT_INICIO_V1",
        "signInWithPassword",
        "getSafeNextPath",
        "ProductPreview",
        "Sua operação inteira",
        "Bem-vindo de volta.",
        "Lembrar meu e-mail",
        "orcalybr@gmail.com",
        "min-h-[100dvh]",
        "next/image"
    )

    foreach ($Text in $RequiredTexts) {
        if (-not $Content.Contains($Text)) {
            throw "Conteúdo obrigatório não encontrado: $Text"
        }

        Write-Host "[OK] $Text" -ForegroundColor Green
    }

    $ForbiddenTexts = @(
        "window.location.href =",
        "dangerouslySetInnerHTML",
        "http://",
        "https://"
    )

    foreach ($Text in $ForbiddenTexts) {
        if ($Content.Contains($Text)) {
            throw "Conteúdo inesperado encontrado: $Text"
        }
    }

    Write-Host "[OK] Autenticação Supabase preservada." -ForegroundColor Green
    Write-Host "[OK] Redirecionamento seguro preservado." -ForegroundColor Green
    Write-Host "[OK] Responsividade 100dvh aplicada." -ForegroundColor Green

    Write-Section "VERIFICANDO O DIFF"

    git --no-pager diff --check -- $RelativePath

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    $Package = Get-Content `
        -LiteralPath (Join-Path $Root "package.json") `
        -Raw |
        ConvertFrom-Json

    if ($Package.scripts.PSObject.Properties.Name -contains "security:check") {
        Write-Section "VALIDANDO SEGURANÇA"

        npm run security:check

        if ($LASTEXITCODE -ne 0) {
            throw "security:check falhou."
        }

        Write-Host "[OK] SECURITY_CHECK_EXIT_CODE=0" -ForegroundColor Green
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Section "EXECUTANDO BUILD COMPLETO"

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou."
    }

    Write-Section "LOGIN SIGNATURE APLICADO"

    Write-Host "Arquivo: $RelativePath"
    Write-Host "Backup: $BackupPath"
    Write-Host "Build: aprovado"
    Write-Host "Commit: não realizado"
    Write-Host "Deploy: não realizado"
    Write-Host ""
    Write-Host "Novo visual:" -ForegroundColor Cyan
    Write-Host "  - mockup vivo do painel no desktop"
    Write-Host "  - experiência premium e cinematográfica"
    Write-Host "  - formulário com profundidade e microinterações"
    Write-Host "  - mobile compacto com resumo operacional"
    Write-Host "  - campos com foco elevado e feedback visual"
    Write-Host "  - autenticação e redirecionamento preservados"
}
catch {
    Restore-Login
    throw
}
